<?php
$summary=$report['summary'];
$maxDaily=max(1,...array_map(fn($d)=>max((int)$d['visits'],(int)$d['pageviews']),$report['daily']));
$renderRank=function(string $title,array $rows,string $empty='No activity in this period.') { $max=max(1,...array_map(fn($r)=>(int)$r['value'],$rows?:[['value'=>1]])); ?>
<section class="analytics-panel"><h3><?= e($title) ?></h3><?php if(!$rows): ?><div class="empty-state compact"><span><?= e($empty) ?></span></div><?php else: ?><ol class="analytics-rank"><?php foreach($rows as $row): ?><li><span><?= e($row['label']) ?></span><span class="analytics-bar"><i style="width:<?= round((int)$row['value']/$max*100,1) ?>%"></i></span><strong><?= (int)$row['value'] ?></strong></li><?php endforeach; ?></ol><?php endif; ?></section><?php };
?>
<nav class="analytics-tabs" aria-label="Analytics sections"><a class="active" href="<?= e_attr($basePath) ?>/admin/analytics">Dashboard</a><a href="<?= e_attr($basePath) ?>/admin/analytics/visitors">Visitor Explorer</a><a href="<?= e_attr($basePath) ?>/admin/analytics/geography">Geography</a></nav>
<section class="analytics-hero"><div><p class="section-kicker">First-party intelligence</p><h2>Your audience, without surveillance</h2><p>Anonymous, privacy-respecting insight across Core and every installed industry module. No Google Analytics account is required.</p><div class="analytics-presets"><a href="<?= e_attr($basePath) ?>/admin/analytics&from=<?= date('Y-m-d',time()-6*86400) ?>&to=<?= date('Y-m-d') ?>">7 days</a><a href="<?= e_attr($basePath) ?>/admin/analytics&from=<?= date('Y-m-d',time()-29*86400) ?>&to=<?= date('Y-m-d') ?>">30 days</a><a href="<?= e_attr($basePath) ?>/admin/analytics&from=<?= date('Y-m-d',time()-89*86400) ?>&to=<?= date('Y-m-d') ?>">90 days</a></div></div><form class="analytics-range" method="get" action="<?= e_attr($siteBasePath) ?>/index.php"><input type="hidden" name="p" value="/admin/analytics"><label>From<input type="date" name="from" value="<?= e_attr($report['from']) ?>"></label><label>To<input type="date" name="to" value="<?= e_attr($report['to']) ?>"></label><button class="btn">Apply</button><a class="btn secondary" href="<?= e_attr($basePath) ?>/admin/analytics/export&from=<?= e_attr($report['from']) ?>&to=<?= e_attr($report['to']) ?>">Export CSV</a></form></section>
<section class="analytics-metrics">
<div><span>Visitors</span><strong><?= (int)$summary['visits'] ?></strong><small>Anonymous sessions</small></div><div><span>Pageviews</span><strong><?= (int)$summary['pageviews'] ?></strong><small>Successful public pages</small></div><div class="live"><span>Live now</span><strong data-analytics-live><?= (int)$summary['live'] ?></strong><small>Seen within 60 seconds</small></div><div><span>Bounce rate</span><strong><?= e(number_format((float)$summary['bounce_rate'],1)) ?>%</strong><small>Completed single-page visits</small></div><div><span>Avg. active time</span><strong><?= gmdate('i:s',(int)$summary['avg_active']) ?></strong><small>Visible-tab time</small></div>
</section>
<section class="card analytics-traffic"><div class="card-heading"><div><p class="section-kicker">Traffic</p><h2>Visitors and pageviews</h2></div><span class="badge neutral"><?= e($report['from']) ?> — <?= e($report['to']) ?></span></div><div class="analytics-chart" role="img" aria-label="Daily visitors and pageviews"><div class="analytics-legend"><span><i class="visits"></i>Visitors</span><span><i class="views"></i>Pageviews</span></div><div class="analytics-columns"><?php foreach($report['daily'] as $day): ?><div class="analytics-day"><div class="bars"><i class="visits" style="height:<?= max(2,round((int)$day['visits']/$maxDaily*100)) ?>%" title="<?= (int)$day['visits'] ?> visitors"></i><i class="views" style="height:<?= max(2,round((int)$day['pageviews']/$maxDaily*100)) ?>%" title="<?= (int)$day['pageviews'] ?> pageviews"></i></div><small><?= e(date('M j',strtotime($day['date']))) ?></small></div><?php endforeach; ?></div></div></section>
<div class="analytics-grid"><?php $renderRank('Popular pages',$report['pages']);$renderRank('Acquisition channels',$report['channels']);$renderRank('Referrals',$report['referrers']);$renderRank('Campaigns',$report['campaigns']);$renderRank('Supplied search terms',$report['search_terms']);$renderRank('Countries',$report['countries']);$renderRank('Devices',$report['devices']);$renderRank('Browsers',$report['browsers']);$renderRank('Operating systems',$report['systems']);$renderRank('Entry pages',$report['entry_pages']);$renderRank('Exit pages',$report['exit_pages']);$renderRank('Session depth',$report['depth']);$renderRank('Active-time engagement',$report['engagement']);$renderRank('Crawler traffic',$report['crawlers'],'No crawler traffic in this period.'); ?></div>
<section class="card analytics-heatmap"><div class="card-heading"><div><p class="section-kicker">Timing</p><h2>Weekly activity</h2><p class="card-subtitle">Darker cells represent more session starts. Times use the website timezone.</p></div></div><div class="heatmap-scroll"><table aria-label="Visitor activity by weekday and hour"><thead><tr><th>Day</th><?php foreach(range(0,23) as $hour): ?><th><?= $hour%3===0?e(date('ga',mktime($hour))):'' ?></th><?php endforeach; ?></tr></thead><tbody><?php $heatMax=max(1,...array_map(fn($row)=>max($row),$report['heatmap']));foreach(['Sun','Mon','Tue','Wed','Thu','Fri','Sat'] as $day=>$label): ?><tr><th><?= e($label) ?></th><?php foreach($report['heatmap'][$day] as $value): ?><td><i style="opacity:<?= $value?number_format(.16+.84*$value/$heatMax,2):0 ?>" title="<?= (int)$value ?> visits"></i></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></section>
<div class="dashboard-grid analytics-bottom"><section class="card"><div class="card-heading"><div><p class="section-kicker">Search visibility</p><h2>Google Search Console</h2><p class="card-subtitle">Import a Search Console query CSV to add clicks, impressions, CTR, and average position. It remains separate from first-party traffic.</p></div></div><?php if($searchConsole): ?><table><thead><tr><th>Query</th><th>Clicks</th><th>Impressions</th><th>CTR</th><th>Position</th></tr></thead><tbody><?php foreach(array_slice($searchConsole,0,8) as $row): ?><tr><td><?= e($row['query_text']) ?></td><td><?= (int)$row['clicks'] ?></td><td><?= (int)$row['impressions'] ?></td><td><?= e(number_format((float)$row['ctr']*100,1)) ?>%</td><td><?= e(number_format((float)$row['average_position'],1)) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?><form method="post" action="<?= e_attr($basePath) ?>/admin/analytics/search-console" enctype="multipart/form-data"><?= $csrf->field() ?><div class="grid2"><label>Date range begins<input type="date" name="range_start"></label><label>Date range ends<input type="date" name="range_end"></label></div><label>Search Console CSV<input type="file" name="search_csv" accept=".csv,text/csv" required><small>Maximum 2 MiB and 5,000 query rows.</small></label><div class="button-row"><button class="btn">Import report</button><?php if($searchConsole): ?><button class="btn secondary" name="action" value="remove" formnovalidate data-confirm="Remove the imported Search Console report?">Remove import</button><?php endif; ?></div></form></section>
<section class="card"><p class="section-kicker">Collection controls</p><h2>Privacy and retention</h2><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="settings"><label class="switch-row"><span><strong>Collect anonymous analytics</strong><small>Excludes staff, previews, DNT, and Global Privacy Control.</small></span><input type="checkbox" name="enabled" value="1" <?= $settings['enabled']?'checked':'' ?> role="switch"></label><label class="switch-row"><span><strong>Separate crawler traffic</strong><small>Bot visits never inflate human visitor reports.</small></span><input type="checkbox" name="crawlers_enabled" value="1" <?= $settings['crawlers']?'checked':'' ?> role="switch"></label><label class="switch-row"><span><strong>Approximate geography</strong><small>Uses trusted host-provided country data when available.</small></span><input type="checkbox" name="geography_enabled" value="1" <?= $settings['geography']?'checked':'' ?> role="switch"></label><label>Retention<select name="retention_days"><?php foreach([30,90,180,365] as $days): ?><option value="<?= $days ?>" <?= $settings['retention']===$days?'selected':'' ?>><?= $days ?> days</option><?php endforeach; ?></select></label><button class="btn">Save controls</button></form><form method="post" class="analytics-cleanup"><?= $csrf->field() ?><input type="hidden" name="action" value="cleanup"><button class="btn secondary">Run retention cleanup now</button></form><div class="privacy-note"><strong>Designed for privacy</strong><p>Core stores neither raw IP addresses nor full user-agent strings. Visitor identifiers are installation-keyed hashes and are not shared with third parties.</p></div></section></div>
